import { AlertTriangle, ArrowDownRight, Crosshair, FileSearch, Flame, ShieldAlert, Target, TrendingUp } from 'lucide-react'

export type GraphIntelligence = {
  topPriorityNodes: Array<{ id: string; label: string; kind: string; priority: number; risk: number; confidence: number; conflicts: number; degree: number }>
  attackPriorityPaths: Array<{ root: string; label: string; priority: number; blastRadius: number; maxImpact: number }>
  executivePriority: number
  riskExposure: number
  highImpactNodes: number
  conflictedNodes: number
  evidenceBackedNodes: number
}

export function AssuranceGraphIntelligencePanel({ intelligence, onInvestigate }: { intelligence?: GraphIntelligence; onInvestigate?: (id: string) => void }) {
  if (!intelligence) return null
  return <section className="space-y-4"><header className="flex items-center gap-2"><Flame className="h-4 w-4 text-primary" /><div><div className="font-semibold">Graph Intelligence</div><p className="text-xs text-muted-foreground">Prioritized paths, risk propagation, evidence strength, and executive impact.</p></div></header><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-5"><Kpi icon={<Target className="h-4 w-4" />} label="Executive priority" value={intelligence.executivePriority} suffix="/100" /><Kpi icon={<ShieldAlert className="h-4 w-4" />} label="Risk exposure" value={intelligence.riskExposure} suffix="/100" /><Kpi icon={<ArrowDownRight className="h-4 w-4" />} label="High impact nodes" value={intelligence.highImpactNodes} /><Kpi icon={<AlertTriangle className="h-4 w-4" />} label="Conflicted nodes" value={intelligence.conflictedNodes} /><Kpi icon={<FileSearch className="h-4 w-4" />} label="Evidence-backed" value={intelligence.evidenceBackedNodes} /></div><div className="grid gap-4 lg:grid-cols-2"><div className="rounded-2xl border bg-card"><div className="border-b px-5 py-4"><div className="flex items-center gap-2 text-sm font-semibold"><Crosshair className="h-4 w-4 text-primary" /> Top investigation priorities</div><p className="mt-1 text-[11px] text-muted-foreground">Nodes with the highest composite security priority.</p></div><div className="divide-y">{intelligence.topPriorityNodes.slice(0, 8).map((node, index) => <button key={node.id} type="button" onClick={() => onInvestigate?.(node.id)} className="flex w-full items-center gap-3 px-5 py-3 text-left hover:bg-muted/30"><span className="grid h-7 w-7 place-items-center rounded-lg border bg-background text-[10px] font-black">{index + 1}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">{node.label}</span><span className="mt-0.5 block text-[10px] text-muted-foreground">{node.kind} · risk {Math.round(node.risk)} · confidence {Math.round(node.confidence)}%</span></span><span className="text-right"><span className="block text-sm font-black">{Math.round(node.priority)}</span><span className="text-[9px] uppercase tracking-wider text-muted-foreground">priority</span></span></button>)}</div></div><div className="rounded-2xl border bg-card"><div className="border-b px-5 py-4"><div className="flex items-center gap-2 text-sm font-semibold"><TrendingUp className="h-4 w-4 text-primary" /> Attack priority paths</div><p className="mt-1 text-[11px] text-muted-foreground">Ranked paths by impact, blast radius, and node priority.</p></div><div className="divide-y">{intelligence.attackPriorityPaths.slice(0, 8).map((path, index) => <div key={`${path.root}-${index}`} className="flex items-center gap-3 px-5 py-3"><span className="grid h-7 w-7 place-items-center rounded-lg border bg-background text-[10px] font-black">{index + 1}</span><div className="min-w-0 flex-1"><div className="truncate text-xs font-semibold">{path.label}</div><div className="mt-0.5 text-[10px] text-muted-foreground">Blast radius {path.blastRadius} · max impact {Math.round(path.maxImpact)}</div></div><div className="text-right"><div className="text-sm font-black">{Math.round(path.priority)}</div><div className="text-[9px] uppercase tracking-wider text-muted-foreground">priority</div></div></div>)}</div></div></div></section>
}
function Kpi({ icon, label, value, suffix = '' }: { icon: React.ReactNode; label: string; value: number; suffix?: string }) { return <div className="rounded-xl border bg-card p-4"><div className="flex items-center gap-2 text-[10px] uppercase tracking-wider text-muted-foreground">{icon}{label}</div><div className="mt-2 text-2xl font-black">{Math.round(value)}<span className="ml-1 text-xs font-medium text-muted-foreground">{suffix}</span></div></div> }
